mapper.select:
SELECT 
    a.APPROVAL_ID,
    a.DATA_ID,
    a.WORKFLOW_ID,
    a.NODE_CODE,
    a.NODE_NAME,
    a.APPROVER_ID,
    a.APPROVER_NAME,
    a.APPROVAL_STATUS,
    a.APPROVAL_COMMENT,
    a.APPROVAL_TIME,
    a.CREATE_USER,
    a.CREATE_TIME,
    d.PERIOD,
    d.VERSION,
    m.MODEL_NAME
FROM TBL_BUDGET_APPROVAL a
LEFT JOIN TBL_BUDGET_DATA d ON a.DATA_ID = d.DATA_ID
LEFT JOIN TBL_BUDGET_MODEL m ON d.MODEL_ID = m.MODEL_ID
WHERE a.ORG_ID = #{param.orgId}

    AND a.DATA_ID = #{param.dataId}


    AND a.APPROVER_ID = #{param.approverId}


    AND a.APPROVAL_STATUS = #{param.approvalStatus}


    AND d.PERIOD = #{param.period}


    AND d.VERSION = #{param.version}


    AND d.MODEL_ID = #{param.modelId}


    AND a.CREATE_TIME >= #{param.startTime}


    AND a.CREATE_TIME <= #{param.endTime}

ORDER BY a.CREATE_TIME DESC

SELECT a.APPROVAL_ID, a.DATA_ID, a.WORKFLOW_ID, a.NODE_CODE, a.NODE_NAME, a.APPROVER_ID, a.APPROVER_NAME, a.APPROVAL_STATUS, a.APPROVAL_COMMENT, a.APPROVAL_TIME, a.CREATE_USER, a.CREATE_TIME, d.PERIOD, d.VERSION, d.SUBMIT_USER, su.REALNAME AS SUBMIT_USER_NAME, m.MODEL_NAME FROM TBL_BUDGET_APPROVAL a LEFT JOIN TBL_BUDGET_DATA d ON a.DATA_ID = d.DATA_ID LEFT JOIN TBL_BUDGET_MODEL m ON d.MODEL_ID = m.MODEL_ID LEFT JOIN TBL_STAFF su ON d.SUBMIT_USER = TO_CHAR(su.STAFFID) WHERE a.APPROVER_ID = #{param.approverId} AND a.APPROVAL_STATUS = 'PENDING' AND a.ORG_ID = #{param.orgId}
AND d.PERIOD LIKE CONCAT('%', #{param.period}, '%')
AND d.VERSION LIKE CONCAT('%', #{param.version}, '%')
AND d.MODEL_ID = #{param.modelId}
AND m.MODEL_NAME LIKE CONCAT('%', #{param.modelName}, '%')
ORDER BY a.CREATE_TIME DESC

SELECT a.APPROVAL_ID, a.DATA_ID, a.WORKFLOW_ID, a.NODE_CODE, a.NODE_NAME, a.APPROVER_ID, a.APPROVER_NAME, a.APPROVAL_STATUS, a.APPROVAL_COMMENT, a.APPROVAL_TIME, a.CREATE_USER, a.CREATE_TIME, d.PERIOD, d.VERSION, d.SUBMIT_USER, su.REALNAME AS SUBMIT_USER_NAME, m.MODEL_NAME FROM TBL_BUDGET_APPROVAL a LEFT JOIN TBL_BUDGET_DATA d ON a.DATA_ID = d.DATA_ID LEFT JOIN TBL_BUDGET_MODEL m ON d.MODEL_ID = m.MODEL_ID LEFT JOIN TBL_STAFF su ON d.SUBMIT_USER = TO_CHAR(su.STAFFID) WHERE a.APPROVER_ID = #{param.approverId} AND a.APPROVAL_STATUS IN ('APPROVED', 'REJECTED') AND a.ORG_ID = #{param.orgId}
AND d.PERIOD LIKE CONCAT('%', #{param.period}, '%')
AND d.VERSION LIKE CONCAT('%', #{param.version}, '%')
AND d.MODEL_ID = #{param.modelId}
AND m.MODEL_NAME LIKE CONCAT('%', #{param.modelName}, '%')
AND a.APPROVAL_TIME >= #{param.startTime}
AND a.APPROVAL_TIME <= #{param.endTime}
ORDER BY a.APPROVAL_TIME DESC
